mcp:tool-listener.mcp:parameters-schema:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "type": "object",
  "properties": {
    "name": {
      "type": "string",
      "description": "Filter by opportunity name (case-insensitive substring match)"
    },
    "priority": {
      "type": "string",
      "enum": ["High", "Medium", "Low"],
      "description": "Filter by exact priority"
    },
    "highPriorityOnly": {
      "type": "boolean",
      "description": "If true, only return High priority opportunities",
      "default": false
    },
    "stageName": {
      "type": "string",
      "description": "Filter by exact stage name, e.g. 'Qualification', 'Value Proposition', 'Closed Won', 'Closed Lost'"
    }
  },
  "required": []
}

{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "type": "object",
  "properties": {
    "oppId": {
      "type": "string",
      "description": "The unique ID of the opportunity to update, e.g. '0068000000Lx1AA'"
    },
    "amount": {
      "type": "number",
      "description": "Deal amount in USD"
    },
    "stageName": {
      "type": "string",
      "description": "Sales stage, e.g. 'Qualification', 'Negotiation/Review'"
    },
    "priority": {
      "type": "string",
      "enum": ["High", "Medium", "Low"]
    },
    "probability": {
      "type": "number",
      "description": "Win probability percentage (0-100)"
    },
    "closeDate": {
      "type": "string",
      "description": "Expected close date, format yyyy-MM-dd"
    },
    "nextStep": {
      "type": "string",
      "description": "Next action to take on this opportunity"
    }
  },
  "required": ["oppId"]
}

{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "type": "object",
  "properties": {
    "oppId": {
      "type": "string",
      "description": "The unique ID of the opportunity to close"
    },
    "stageName": {
      "type": "string",
      "enum": ["Closed Won", "Closed Lost"],
      "description": "Final stage — must be 'Closed Won' or 'Closed Lost'"
    },
    "actualAmount": {
      "type": "number",
      "description": "Actual closed amount, if different from the original amount"
    },
    "closeReason": {
      "type": "string",
      "description": "Reason or note for closing the opportunity"
    }
  },
  "required": ["oppId", "stageName"]
}
